package service;

import domain.Member;
import domain.MemberStatement;
import infra.PtsctlClient;
import store.EarnLedger;

import java.time.YearMonth;

/** Member-facing points summary. The balance is the vendor's, not ours. */
public class StatementService {
    private final MemberDirectory members;
    private final EarnLedger ledger;
    private final PtsctlClient pts;

    public StatementService(MemberDirectory members, EarnLedger ledger, PtsctlClient pts) {
        this.members = members;
        this.ledger = ledger;
        this.pts = pts;
    }

    public MemberStatement statement(String memberNo, YearMonth month) {
        Member m = members.find(memberNo).orElseThrow(() -> new IllegalArgumentException("unknown member " + memberNo));
        long balance = pts.balance(m.memberNo());
        int entries = pts.history(m.memberNo()).size();
        return new MemberStatement(m.memberNo(), m.name(), m.grade(), balance, entries,
                ledger.earnedIn(m.memberNo(), month));
    }
}
package service;

import domain.EarnEntry;
import domain.Member;
import store.EarnLedger;

import java.time.YearMonth;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Marketing's monthly "top earners" list, from what the earn run sent to the vendor this
 * month (our own earn ledger), not from the vendor balance.
 */
// TODO: the member app already shows the vendor balance -- do we still need our own count here?
public class TopEarnersReport {
    public record Row(String memberNo, String name, long points) {}

    private final MemberDirectory members;
    private final EarnLedger ledger;

    public TopEarnersReport(MemberDirectory members, EarnLedger ledger) {
        this.members = members;
        this.ledger = ledger;
    }

    public List<Row> top(YearMonth month, int n) {
        Map<String, Long> sums = new LinkedHashMap<>();
        for (EarnEntry e : ledger.all()) {
            if (YearMonth.from(e.day()).equals(month)) sums.merge(e.memberNo(), e.points(), Long::sum);
        }
        List<Row> rows = new ArrayList<>();
        for (Map.Entry<String, Long> s : sums.entrySet()) {
            String name = members.find(s.getKey()).map(Member::name).orElse("?");
            rows.add(new Row(s.getKey(), name, s.getValue()));
        }
        rows.sort(Comparator.comparingLong(Row::points).reversed().thenComparing(Row::memberNo));
        return rows.size() > n ? rows.subList(0, n) : rows;
    }
}
package service;

import domain.Member;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Member lookup. Keys are the member number exactly as issued (text, not a number). */
public class MemberDirectory {
    private final Map<String, Member> members = new LinkedHashMap<>();

    public MemberDirectory(List<Member> list) {
        for (Member m : list) {
            String key = key(m.memberNo());
            if (members.putIfAbsent(key, m) != null) {
                throw new IllegalStateException("member number issued twice: " + m.memberNo());
            }
        }
    }

    public Optional<Member> find(String memberNo) {
        return Optional.ofNullable(members.get(key(memberNo)));
    }

    public List<Member> all() {
        return List.copyOf(members.values());
    }

    /** Corporate codes are case-insensitive on the acquirer side ("c7781" == "C7781"). */
    static String key(String memberNo) {
        return memberNo.strip().toUpperCase();
    }
}
package infra;

import domain.Grade;
import domain.Member;
import domain.Payment;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/** Fixture/export readers. Values never contain commas. */
public final class CsvFiles {
    private CsvFiles() {}

    public static List<Member> members(Path file) {
        List<Member> out = new ArrayList<>();
        for (String[] r : rows(file)) {
            out.add(new Member(cell(r[0]), r[1], Grade.valueOf(r[2]), r[3]));
        }
        return out;
    }

    public static List<Payment> payments(Path file) {
        List<Payment> out = new ArrayList<>();
        for (String[] r : rows(file)) {
            out.add(new Payment(r[0], cell(r[1]), r[2], Long.parseLong(r[3]), r[4]));
        }
        return out;
    }

    /**
     * The acquirer's payment export is made for spreadsheets: member numbers that start
     * with 0 are written as ="004512" so the spreadsheet keeps them as text.
     */
    static String cell(String raw) {
        String s = raw.strip();
        if (s.startsWith("=\"") && s.endsWith("\"") && s.length() >= 3) {
            return s.substring(2, s.length() - 1);
        }
        if (s.length() >= 2 && s.startsWith("\"") && s.endsWith("\"")) {
            return s.substring(1, s.length() - 1);
        }
        return s;
    }

    private static List<String[]> rows(Path file) {
        try {
            List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
            List<String[]> rows = new ArrayList<>();
            for (int i = 1; i < lines.size(); i++) {
                String l = lines.get(i).strip();
                if (!l.isEmpty()) rows.add(l.split(",", -1));
            }
            return rows;
        } catch (IOException e) {
            throw new IllegalStateException("cannot read " + file, e);
        }
    }
}
