package service;

import domain.Member;
import infra.PtsctlClient;

/**
 * Customer-care compensation points, paid for a support ticket. The vendor reference is
 * A-<ticket no>, which the vendor accepts once per ledger, so a ticket pays once. Compensation is
 * not written to our earn ledger: the monthly top earners and the payment reconciliation count
 * payment earns only.
 */
public class CompensationService {
    static final String REF_PREFIX = "A";

    private final MemberDirectory members;
    private final PtsctlClient pts;

    public CompensationService(MemberDirectory members, PtsctlClient pts) {
        this.members = members;
        this.pts = pts;
    }

    /** Credits compensation points; returns the vendor entry number. Refuses before any credit is sent. */
    public String compensate(String memberNo, long points, String ticketNo) {
        if (memberNo == null || memberNo.isBlank()) throw new IllegalArgumentException("member number is required");
        if (points <= 0) throw new IllegalArgumentException("compensation points must be positive: " + points);
        if (ticketNo == null || !ticketNo.matches("[A-Za-z0-9-]{1,30}")) {
            throw new IllegalArgumentException("bad ticket number: " + ticketNo);
        }
        Member m = members.find(memberNo).orElseThrow(() -> new IllegalArgumentException("unknown member " + memberNo));
        return pts.earn(m.memberNo(), points, REF_PREFIX + "-" + ticketNo);
    }
}

